<script setup>
import { onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import http from '@/services/http'
const route=useRoute(); const cv=ref(null); const erreur=ref('')
onMounted(async()=>{try{cv.value=(await http.get(`/candidat/cv/${route.params.candidatId}`)).data}catch(e){erreur.value=e.response?.data?.message||'CV introuvable.'}})
</script>
<template><div class="container py-4"><h1 class="h3 mb-4">CV du salarié</h1><p v-if="erreur" class="alert alert-danger">{{ erreur }}</p><div v-else-if="cv" class="d-grid gap-3"><section class="card"><div class="card-body"><h2 class="h5">{{ cv.prenom }} {{ cv.nom }}</h2><p class="text-body-secondary mb-0">{{ cv.email }} · {{ cv.telephone }}</p><p v-if="cv.adresse" class="mb-0">{{ cv.adresse }}</p></div></section><section v-if="cv.profil" class="card"><div class="card-body"><h2 class="h5">Profil</h2><p class="mb-0">{{ cv.profil }}</p></div></section><section class="card"><div class="card-body"><h2 class="h5">Formation</h2><p>{{ cv.diplome || '—' }}<span v-if="cv.etablissement"> · {{ cv.etablissement }}</span><span v-if="cv.annee"> ({{ cv.annee }})</span></p><div v-for="f in cv.formations" :key="`${f.diplome}-${f.annee}`" class="mb-2"><strong>{{ f.diplome }}</strong> — {{ f.etablissement }} <span v-if="f.annee">({{ f.annee }})</span></div></div></section><section v-if="cv.experiences?.length" class="card"><div class="card-body"><h2 class="h5">Expériences professionnelles</h2><article v-for="e in cv.experiences" :key="`${e.poste}-${e.entreprise}-${e.periode}`" class="border-bottom py-2"><strong>{{ e.poste }}</strong><span v-if="e.entreprise"> · {{ e.entreprise }}</span><div class="small text-body-secondary">{{ e.periode }}</div><p class="mb-0">{{ e.missions }}</p></article></div></section><section v-if="cv.competences || cv.langues" class="card"><div class="card-body"><h2 class="h5">Compétences et langues</h2><p v-if="cv.competences"><strong>Compétences :</strong> {{ cv.competences }}</p><p v-if="cv.langues" class="mb-0"><strong>Langues :</strong> {{ cv.langues }}</p></div></section></div><p v-else>Chargement…</p></div></template>
